import collections
import math
mod = 1000000007

def multiply(a, b):
	mul = [[0] * 10 for _ in range(10)]
	for i in range(10):
		for j in range(10):
			for k in range(10):
				mul[i][j] += a[i][k] * b[k][j]
				mul[i][j] %= mod
	return mul
